<script lang="ts">
 import { apiFetch } from '$lib/api'; import { authSession } from '$lib/stores';
 let tab:'adult'|'learner'='adult'; let identifier=''; let password=''; let pin=''; let error='';
 async function submit(){ error=''; try{ const path=tab==='adult'?'/auth/login':'/auth/pin/login'; const body=tab==='adult'?{identifier,password}:{identifier,pin}; const result:any=await apiFetch(path,{method:'POST',body:JSON.stringify(body)}); authSession.set(result.session); location.href=result.redirectTo || (result.session.role==='learner'?'/dashboard/learner':`/dashboard/${result.session.role}`);}catch{error='We could not sign you in. Check your details and try again.'}}
</script><main class="shell"><header class="top"><a href="/" style="color:white">Learnzur</a><strong>Login</strong></header><form class="form" on:submit|preventDefault={submit}><div class="tabs"><button type="button" class="btn tab" on:click={()=>tab='adult'}>Parent/Teacher</button><button type="button" class="btn tab" on:click={()=>tab='learner'}>Student (Learner)</button></div><input class="input" bind:value={identifier} placeholder={tab==='adult'?'Email or phone':'Username or name'} />{#if tab==='adult'}<input class="input" bind:value={password} type="password" placeholder="Password" />{:else}<input class="input" bind:value={pin} inputmode="numeric" maxlength="6" placeholder="6-digit PIN" />{/if}{#if error}<p class="muted">{error}</p>{/if}<button class="btn">Sign in</button></form></main>
